Function made <- MakeAdder(amount As Integer)
  Define made As Function(Integer) As Integer <- Function(x As Integer) As Integer
    Return x + amount;
  EndFunction;
EndFunction

Algorithm Add
  Define plusThree As Function(Integer) As Integer <- MakeAdder(3);
  Write plusThree(4);
EndAlgorithm

Function made <- MakeDiscount(percentage As Integer)
  Define made As Function(Integer) As Integer <- Function(price As Integer) As Integer
    Return price - price * percentage Div 100;
  EndFunction;
EndFunction

Function mapped <- Map(v As Vector<Integer>, f As Function(Integer) As Integer)
  Define mapped As Vector<Integer> <- vector();
  For Each elemento In v Do
    mapped.append(f(elemento));
  EndFor
EndFunction

Algorithm Campaigns
  Define percentage As Integer;
  Read percentage;
  Define prices As Vector<Integer> <- vector();
  prices.append(50);
  prices.append(30);
  prices.append(20);
  Define discount As Function(Integer) As Integer <- MakeDiscount(percentage);
  Write Map(prices, discount);
EndAlgorithm
